ALTER TYPE "PlatformRole" ADD VALUE IF NOT EXISTS 'Operations';
CREATE TABLE "operational_incidents" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "reference" VARCHAR(40) NOT NULL, "severity" VARCHAR(20) NOT NULL, "state" VARCHAR(20) NOT NULL DEFAULT 'open', "summary" VARCHAR(500) NOT NULL, "redacted_log" TEXT NOT NULL DEFAULT '', "owner_id" UUID, "opened_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "resolved_at" TIMESTAMPTZ(3), CONSTRAINT "operational_incidents_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "operational_incidents_reference_key" ON "operational_incidents"("reference");
CREATE INDEX "operational_incidents_state_severity_opened_at_idx" ON "operational_incidents"("state", "severity", "opened_at");
CREATE TABLE "restore_drills" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "performed_by" UUID NOT NULL, "environment" VARCHAR(40) NOT NULL, "evidence_ref" VARCHAR(500) NOT NULL, "measured_rpo_mins" INTEGER NOT NULL, "measured_rto_mins" INTEGER NOT NULL, "outcome" VARCHAR(20) NOT NULL, "notes" VARCHAR(2000) NOT NULL DEFAULT '', "performed_at" TIMESTAMPTZ(3) NOT NULL, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "restore_drills_pkey" PRIMARY KEY ("id"), CONSTRAINT "restore_drills_actor_fkey" FOREIGN KEY ("performed_by") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "restore_drills_measurements_check" CHECK ("measured_rpo_mins" >= 0 AND "measured_rto_mins" >= 0), CONSTRAINT "restore_drills_outcome_check" CHECK ("outcome" IN ('passed','failed','partial')));
CREATE INDEX "restore_drills_performed_at_idx" ON "restore_drills"("performed_at");
CREATE TABLE "feature_flag_change_requests" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "flag" VARCHAR(80) NOT NULL, "requested_by" UUID NOT NULL, "desired" BOOLEAN NOT NULL, "reason" VARCHAR(2000) NOT NULL, "state" VARCHAR(20) NOT NULL DEFAULT 'pending', "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "feature_flag_change_requests_pkey" PRIMARY KEY ("id"), CONSTRAINT "feature_flag_requests_actor_fkey" FOREIGN KEY ("requested_by") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "feature_flag_requests_state_check" CHECK ("state" IN ('pending','approved','rejected','cancelled')));
CREATE INDEX "feature_flag_change_requests_flag_state_created_at_idx" ON "feature_flag_change_requests"("flag", "state", "created_at");
